using System;
using System.IO;
using System.Linq;
using Xunit;
using Xunit.Abstractions;

namespace DevelApp.ReDos.Tests
{
    /// <summary>
    /// The committed measurement report (issue #103 acceptance): runs the
    /// full grid - immunity timings, both .NET baselines on identical
    /// inputs, scaling fits, the many-token overhead measurement - and
    /// writes a JSON artifact next to the test assembly. The committed
    /// copy under docs/measurements/redos-immunity/ is generated by this
    /// test; regenerate it after any engine change so the article table
    /// always rests on fresh measured numbers.
    /// </summary>
    public class RedosMeasurementReportTests
    {
        private readonly ITestOutputHelper _output;

        public RedosMeasurementReportTests(ITestOutputHelper output)
        {
            _output = output;
        }

        [Fact]
        public void MeasurementReport_IsGenerated_WithAllEnginesAndFits()
        {
            var report = RedosMeasurementReport.Build();

            // Sanity: the report must contain every catalog pattern and
            // the baseline + scaling evidence the issue requires.
            Assert.Equal(
                RedosPatternCatalog.ArticleAndCorpusPatterns.Count + RedosPatternCatalog.ScalingPatterns.Count + 1,
                report.Patterns.Count);
            Assert.All(
                report.Patterns.Where(p => !p.SupportedByStepLexer),
                p => Assert.NotNull(p.Backtracking));
            Assert.All(
                report.Patterns.Where(p => p.SupportedByStepLexer && p.Scaling is not null),
                p =>
                {
                    Assert.True(p.Scaling!.R2 >= 0.90, $"{p.Name}: report fit R² {p.Scaling.R2:F4} too low");
                    Assert.True(
                        p.Scaling.GrowthRatioHundredKbOverSixteenKb <= 12.0,
                        $"{p.Name}: report growth ratio {p.Scaling.GrowthRatioHundredKbOverSixteenKb:F2} too high (linear 6.25, quadratic 39)");
                });
            Assert.All(report.Patterns, p => Assert.NotEmpty(p.StepLexer));

            // The corpus honesty check: every pattern flagged as a
            // traditional-engine blowup must actually blow up the .NET
            // backtracking engine on the recorded adversarial input (that
            // is the evidence the article table cites), and every pattern
            // flagged as not-a-blowup - the two unanchored article
            // patterns - must complete, so the corpus cannot silently
            // drift. If an assertion fires, either the pattern or the
            // baseline engine changed and the entry must be re-examined.
            foreach (var entry in report.Patterns.Where(p => p.Backtracking is not null))
            {
                if (entry.ExpectedBacktrackingBlowup)
                {
                    Assert.True(
                        entry.Backtracking!.TimedOut,
                        $"{entry.Name}: the backtracking baseline unexpectedly completed on its adversarial input "
                            + $"({entry.Backtracking.Milliseconds:F1} ms at {entry.Backtracking.LengthBytes} bytes); "
                            + "the corpus entry no longer demonstrates a blowup and must be re-examined.");
                }
                else
                {
                    Assert.False(
                        entry.Backtracking!.TimedOut,
                        $"{entry.Name}: the backtracking baseline unexpectedly timed out; "
                            + "the entry's expected outcome must be re-examined.");
                }
            }

            var artifactPath = Path.Combine(AppContext.BaseDirectory, "redos-immunity-report.json");
            File.WriteAllText(artifactPath, report.ToJson());

            _output.WriteLine($"Report written to {artifactPath}");
            _output.WriteLine($"Engine under test: {report.EngineUnderTest}");
            _output.WriteLine($"Runtime: {report.DotNetRuntime}");
            _output.WriteLine($"OS: {report.OperatingSystem} ({report.ProcessorCount} logical processors, {report.Globalization} globalization)");

            foreach (var pattern in report.Patterns)
            {
                var largest = pattern.StepLexer.Last();
                _output.WriteLine(
                    $"{pattern.Name}: StepLexer {largest.LengthBytes / 1024.0:F0}KB={largest.Milliseconds:F3} ms; " +
                    $"NonBacktracking 100KB={(pattern.NonBacktracking.Count == 0 ? "n/a" : $"{pattern.NonBacktracking.Last().Milliseconds:F3} ms")}; " +
                    (pattern.Backtracking is null
                        ? "backtracking: n/a"
                        : pattern.Backtracking.TimedOut
                            ? $"backtracking: > {pattern.Backtracking.TimeoutMs} ms (timeout at {pattern.Backtracking.LengthBytes} bytes)"
                            : $"backtracking: {pattern.Backtracking.Milliseconds:F3} ms at {pattern.Backtracking.LengthBytes} bytes") +
                    (pattern.Scaling is null
                        ? string.Empty
                        : $"; fit {pattern.Scaling.NanosecondsPerByte:F1} ns/byte, R²={pattern.Scaling.R2:F4}, growth 100KB/16KB={pattern.Scaling.GrowthRatioHundredKbOverSixteenKb:F2}"));
            }
        }
    }
}
